const total = ctx.words.length;
const latest = Math.max(ctx.duration - 0.6, 0);
const cue = (fraction) => Math.min(ctx.at(Math.min(Math.round(fraction * (total - 1)), total - 1)), latest);
const wordsFrom = (start, count) => ctx.words.slice(start, start + count).map((word) => word.text).join(" ");
const clean = (text, limit) => text.replace(/[^\p{L}\p{N}]/gu, "").slice(0, limit);
const SVG_NS = "http://www.w3.org/2000/svg";
const COUNT = 4;
const svgElement = (name, attributes) => {
  const element = document.createElementNS(SVG_NS, name);
  Object.entries(attributes).forEach(([key, value]) => element.setAttribute(key, String(value)));
  return element;
};
const { width, height } = ctx.safeArea;
const horizontal = ctx.aspect === "16:9";
const boxWidth = horizontal ? 340 : Math.min(560, width * 0.7);
const boxHeight = horizontal ? 190 : 150;
const wordIndex = (step) => Math.min(Math.round((step / (COUNT - 1)) * (total - 1)), total - 1);
const centers = Array.from({ length: COUNT }, (_, step) => {
  if (horizontal) {
    const gap = (width - boxWidth * COUNT) / (COUNT - 1);
    return { x: boxWidth / 2 + step * (boxWidth + gap), y: height / 2 };
  }
  const gap = (height - boxHeight * COUNT) / (COUNT - 1);
  return { x: width / 2, y: boxHeight / 2 + step * (boxHeight + gap) };
});
const host = document.createElement("div");
host.className = "mo-f-host";
ctx.root.append(host);
const svg = svgElement("svg", { class: "mo-f-diagram", viewBox: "0 0 " + width + " " + height });
const nodes = centers.map((center, step) => {
  const group = svgElement("g", {});
  group.append(
    svgElement("rect", {
      class: "mo-f-box",
      x: center.x - boxWidth / 2,
      y: center.y - boxHeight / 2,
      width: boxWidth,
      height: boxHeight,
      rx: 28,
    }),
  );
  const step_label = svgElement("text", { class: "mo-f-step", x: center.x, y: center.y - boxHeight * 0.28 });
  step_label.textContent = "0" + (step + 1);
  const label = svgElement("text", { class: "mo-f-label", x: center.x, y: center.y + boxHeight * 0.14 });
  label.textContent = clean(ctx.words[wordIndex(step)].text, 9) || "Step";
  group.append(step_label, label);
  svg.append(group);
  return group;
});
const edges = centers.slice(1).map((to, step) => {
  const from = centers[step];
  const inset = 18;
  const d = horizontal
    ? "M " + (from.x + boxWidth / 2 + inset) + " " + from.y + " L " + (to.x - boxWidth / 2 - inset) + " " + to.y
    : "M " + from.x + " " + (from.y + boxHeight / 2 + inset) + " L " + to.x + " " + (to.y - boxHeight / 2 - inset);
  const edge = svgElement("path", { class: "mo-f-edge", d, pathLength: 1 });
  svg.append(edge);
  return edge;
});
host.append(svg);
nodes.forEach((node, step) => {
  ctx.timeline.from(
    node,
    { opacity: 0, scale: 0.9, transformOrigin: "50% 50%", duration: 0.45, ease: "back.out(1.6)" },
    Math.min(ctx.at(wordIndex(step)), latest),
  );
});
edges.forEach((edge, step) => {
  const start = Math.min(Math.max(ctx.at(wordIndex(step)) + 0.2, ctx.at(wordIndex(step + 1)) - 0.7), latest);
  ctx.timeline.fromTo(
    edge,
    { strokeDashoffset: 1 },
    { strokeDashoffset: 0, duration: 0.5, ease: "power2.inOut", immediateRender: true },
    start,
  );
});

