.mo-s-{{sceneId}} .mo-f-host {
  width: 100%;
  height: 100%;
}
.mo-s-{{sceneId}} .mo-f-diagram {
  width: 100%;
  height: 100%;
  overflow: visible;
}
.mo-s-{{sceneId}} .mo-f-box {
  fill: var(--mo-surface);
  stroke: var(--mo-border);
  stroke-width: 3;
}
.mo-s-{{sceneId}} .mo-f-label {
  fill: var(--mo-text);
  font-family: var(--mo-font);
  font-size: var(--mo-text-body);
  font-weight: 700;
  text-anchor: middle;
  dominant-baseline: central;
}
.mo-s-{{sceneId}} .mo-f-step {
  fill: var(--mo-text-muted);
  font-family: var(--mo-font-mono);
  font-size: var(--mo-text-small);
  text-anchor: middle;
  dominant-baseline: central;
}
.mo-s-{{sceneId}} .mo-f-edge {
  fill: none;
  stroke: var(--mo-accent);
  stroke-width: 5;
  stroke-linecap: round;
  stroke-dasharray: 1;
}
